import os
from re import match
from shutil import copy

from hran_pacman.bases.base import DownloaderBase
from hran_pacman.exceptions import PackageComponentNotFound

gsm_builds_remote_addr = r"\\bhlinn12.apac.nsn-net.net/linux_build/BTS_BUILDS"


class GSMPackageDownloader(DownloaderBase):
    technology = "GSM"

    def __init__(self, baseline, variant="reg"):

        super(GSMPackageDownloader, self).__init__(baseline)

        self.baseline = baseline
        self.variant = variant
        self.build_path = self._find_dir(gsm_builds_remote_addr)

    def _find_dir(self, path):
        candidates = [i for i in os.listdir(path) if i in self.baseline]
        if candidates:
            candidate = max(candidates, key=len)
            path = os.path.join(path, candidate)
            path = self._find_dir(path)
        return path

    def get_software_package(self):
        sem_container_path = os.path.join(self.build_path, self.variant)
        if self.build_path == gsm_builds_remote_addr:
            raise PackageComponentNotFound("Software Package " + self.baseline + " not found in " + sem_container_path)
        else:
            msg = "Site Manager " + self.baseline + " not found in " + gsm_builds_remote_addr
            self._copy_first_file_matching_to_pattern(
                sem_container_path, r"^(Flexi_Multiradio[\w_.]+A53[\w.-]*.zip)$", err_msg=msg
            )

    def get_site_manager(self):
        if self.build_path == gsm_builds_remote_addr:
            raise PackageComponentNotFound("Site Manager " + self.baseline + " not found in " + gsm_builds_remote_addr)
        else:
            msg = "Site Manager " + self.baseline + " not found in " + gsm_builds_remote_addr
            self._copy_first_file_matching_to_pattern(
                self.build_path, r"^(2G_BTS_Site_Manager((_[^_]{3,5}){2,3})).zip$", err_msg=msg
            )

    def _copy_first_file_matching_to_pattern(self, container_path, pattern, err_msg):
        for item in os.listdir(container_path):
            if match(pattern, item):
                copy(os.path.join(container_path, item), ".")
                return
        raise PackageComponentNotFound(err_msg)
